#include <bits/stdc++.h>
using namespace std;

struct Order { int orderId, customerId, price; string orderDate; };

class Solution {
public:
    vector<int> reportCustomers(vector<Order>& orders) {
        map<pair<int,int>, long long> sums;
        map<int, pair<int,int>> span;
        for (auto& o : orders) {
            int y = stoi(o.orderDate.substr(0, 4));
            sums[{o.customerId, y}] += o.price;
            auto& s = span[o.customerId];
            s.first = min(s.first ? s.first : INT_MAX, y);
            s.second = max(s.second, y);
        }
        vector<int> res;
        for (auto& [cid, sp] : span) {
            bool ok = true;
            long long prev = LLONG_MIN;
            for (int y = sp.first; y <= sp.second && ok; ++y) {
                auto it = sums.find({cid, y});
                long long cur = it == sums.end() ? 0 : it->second;
                if (cur <= prev) ok = false;
                prev = cur;
            }
            if (ok) res.push_back(cid);
        }
        return res;
    }
};

