import java.util.*;

class Order { int customerId, price; String orderDate; }

class Solution {
    public List<Integer> reportCustomers(List<Order> orders) {
        Map<String, Long> sums = new HashMap<>();
        Map<Integer, int[]> span = new HashMap<>();
        for (Order o : orders) {
            int y = Integer.parseInt(o.orderDate.substring(0, 4));
            sums.merge(o.customerId + "," + y, (long) o.price, Long::sum);
            int[] s = span.computeIfAbsent(o.customerId, k -> new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE});
            s[0] = Math.min(s[0], y);
            s[1] = Math.max(s[1], y);
        }
        List<Integer> res = new ArrayList<>();
        for (var e : span.entrySet()) {
            boolean ok = true;
            long prev = Long.MIN_VALUE;
            for (int y = e.getValue()[0]; y <= e.getValue()[1] && ok; y++) {
                Long v = sums.get(e.getKey() + "," + y);
                long cur = v == null ? 0 : v;
                if (cur <= prev) ok = false;
                prev = cur;
            }
            if (ok) res.add(e.getKey());
        }
        return res;
    }
}

