    }
    const res = [];
    for (const [cid, [lo, hi]] of span) {
        let prev = -Infinity, ok = true;
        for (let y = lo; y <= hi; y++) {
            const cur = sums.has(cid + ',' + y) ? sums.get(cid + ',' + y) : 0;
            if (cur <= prev) { ok = false; break; }
            prev = cur;
        }
        if (ok) res.push(cid);
