import pandas as pd

def report_customers(orders: pd.DataFrame) -> pd.DataFrame:
    orders = orders.copy()
    orders['year'] = orders['order_date'].dt.year
    agg = orders.groupby(['customer_id', 'year'])['price'].sum().reset_index()
    res = []
    for cid, g in agg.groupby('customer_id'):
        full = pd.DataFrame({'year': range(g['year'].min(), g['year'].max() + 1)})
        merged = full.merge(g[['year', 'price']], on='year', how='left').fillna({'price': 0})
        if (merged['price'].diff().dropna() > 0).all():
            res.append(cid)
    return pd.DataFrame({'customer_id': res})

